// auth/ownerBootstrap.ts
var DEFAULT_PLATFORM_OWNER_EMAILS = [
  "iffatabdulsattar68@gmail.com",
  "iffatabdulsattar1010@gmail.com"
];
function platformOwnerEmails() {
  const raw = process.env.EVA_OWNER_EMAILS?.trim();
  const list = raw ? raw.split(",").map((e) => e.trim().toLowerCase()).filter(Boolean) : [...DEFAULT_PLATFORM_OWNER_EMAILS];
  return new Set(list);
}
async function ensureOwnerRole(userId, email) {
  if (!userId || !email) return;
  if (!platformOwnerEmails().has(email.toLowerCase())) return;
  try {
    const admin = await getAdmin();
    if (!admin) return;
    const { data: profile, error: readError } = await admin.from("profiles").select("admin_role").eq("id", userId).maybeSingle();
    if (readError) {
      console.error("[OwnerBootstrap] could not read profile role:", readError.message);
      return;
    }
    if (profile?.admin_role === "OWNER") return;
    const previousRole = profile?.admin_role ?? null;
    const { error: writeError } = await admin.from("profiles").upsert({ id: userId, admin_role: "OWNER" }, { onConflict: "id" });
    if (writeError) {
      console.error("[OwnerBootstrap] could not grant OWNER:", writeError.message);
      return;
    }
    const { error: auditError } = await admin.rpc("log_admin_action", {
      p_actor_id: userId,
      p_actor_email: email.toLowerCase(),
      p_target_id: userId,
      p_target_email: email.toLowerCase(),
      p_action: "PROMOTE_OWNER",
      p_previous_role: previousRole,
      p_new_role: "OWNER",
      p_metadata: { bootstrap: true, source: "owner_allowlist" }
    });
    if (auditError) {
      console.warn("[OwnerBootstrap] audit write skipped:", auditError.message);
    }
    console.log(`[OwnerBootstrap] granted OWNER to allowlisted account ${email}`);
  } catch (err) {
    console.error("[OwnerBootstrap] unexpected error:", err);
  }
}
async function syncPlatformOwners() {
  try {
    const admin = await getAdmin();
    if (!admin) return;
    const { data, error } = await admin.rpc("get_all_users_with_roles");
    if (error || !Array.isArray(data)) {
      if (error) console.error("[OwnerBootstrap] sync listing failed:", error.message);
      return;
    }
    const owners = platformOwnerEmails();
    for (const row of data) {
      if (!row.email || !owners.has(row.email.toLowerCase())) continue;
      if (row.admin_role !== "OWNER") {
        await ensureOwnerRole(row.id, row.email);
      }
    }
  } catch (err) {
    console.error("[OwnerBootstrap] sync error:", err);
  }
}

