// auth/accountRoutes.ts
function registerAccountRoutes(app) {
  app.post("/api/account/onboarding", requireAuth, async (req, res) => {
    const { error } = await supabase.from("profiles").update({
      onboarding_completed: true,
      display_name: req.body?.displayName ? String(req.body.displayName).slice(0, 80) : void 0
    }).eq("id", req.userId);
    if (error) return res.status(500).json({ error: "Could not save your setup." });
    res.json({ ok: true });
  });
  app.post("/api/account/profile", requireAuth, async (req, res) => {
    const displayName = req.body?.displayName === null ? null : String(req.body?.displayName || "").slice(0, 80) || null;
    const { error } = await supabase.from("profiles").update({ display_name: displayName }).eq("id", req.userId);
    if (error) return res.status(500).json({ error: "Could not save your profile." });
    res.json({ ok: true });
  });
  app.post("/api/account/memory-enabled", requireAuth, async (req, res) => {
    const enabled = req.body?.enabled === true;
    const { error } = await supabase.from("user_memory_settings").update({ memory_enabled: enabled }).eq("user_id", req.userId);
    if (error) return res.status(500).json({ error: "Could not change the memory setting." });
    res.json({ ok: true, memoryEnabled: enabled });
  });
  app.post("/api/account/delete", requireAuth, async (req, res) => {
    const password = String(req.body?.password || "");
    const email = req.userEmail;
    if (!password) return res.status(400).json({ error: "Enter your password to confirm deletion." });
    if (!email) return res.status(400).json({ error: "Cannot verify this account." });
    const { error: verifyError } = await supabase.auth.signInWithPassword({ email, password });
    if (verifyError) return res.status(401).json({ error: AUTH_ERRORS.invalidCredentials });
    const userId = req.userId;
    const integrationErrors = [];
    try {
      const admin2 = requireAdmin();
      const { data: connections } = await admin2.from("integration_connections").select("connection_id").eq("user_id", userId);
      if (connections?.length && process.env.COMPOSIO_API_KEY) {
        for (const connection of connections) {
          try {
            await fetch(`${process.env.COMPOSIO_BASE_URL || "https://backend.composio.dev"}/api/v3.1/connections/${connection.connection_id}`, {
              method: "DELETE",
              headers: { "x-api-key": process.env.COMPOSIO_API_KEY }
            });
          } catch {
            integrationErrors.push(connection.connection_id);
          }
        }
      }
    } catch {
    }
    const mem0UserId = `jarvis_user_${userId}`;
    let memoryDeleted = true;
    if (await memoryConfigured(mem0UserId)) {
      try {
        await deleteAllMemories(mem0UserId);
      } catch (error) {
        memoryDeleted = error instanceof Error ? false : true;
      }
    }
    const admin = requireAdmin();
    const { error: purgeError } = await admin.rpc("purge_user_data", { p_user_id: userId });
    if (purgeError) {
      return res.status(500).json({ error: "Account cleanup failed. Your data is intact \u2014 please try again." });
    }
    const { error: authError } = await admin.auth.admin.deleteUser(userId);
    if (authError) {
      return res.status(500).json({ error: "Account removal failed. Please contact support." });
    }
    res.json({
      ok: true,
      warnings: integrationErrors.length ? `${integrationErrors.length} integration(s) could not be disconnected.` : void 0,
      memoryDeleted
    });
  });
}

// auth/googleRoutes.ts
function friendlyAuthError2(message) {
  const m = message.toLowerCase();
  if (m.includes("expired")) return "The sign-in link expired. Please try again.";
  if (m.includes("denied") || m.includes("aborted")) return "Google sign-in was cancelled.";
  return "Google sign-in failed. Please try again.";
}
function registerGoogleRoutes(app) {
  if (!supabaseConfigured) return;
  const redirectBase = process.env.EVA_APP_URL || `http://127.0.0.1:${process.env.EVA_PORT || 3e3}`;
  const redirectUrl = `${redirectBase.replace(/\/$/, "")}/auth/callback`;
  app.get("/api/auth/google", async (_req, res) => {
    const { data, error } = await supabase.auth.signInWithOAuth({
      provider: "google",
      options: {
        redirectTo: redirectUrl,
        // Ask for a fresh consent screen so returning users can switch accounts.
        queryParams: { prompt: "select_account" }
      }
    });
    if (error || !data?.url) {
      res.status(500).json({ error: friendlyAuthError2(error?.message || "no url") });
      return;
    }
    res.json({ url: data.url });
  });
  app.post("/api/auth/google/callback", async (req, res) => {
    const code = String(req.body?.code || "");
    if (!code) {
      res.status(400).json({ error: "The sign-in response is missing required information." });
      return;
    }
    const { data, error } = await supabase.auth.exchangeCodeForSession(code);
    if (error || !data.user || !data.session) {
      res.status(401).json({ error: friendlyAuthError2(error?.message || "exchange failed") });
      return;
    }
    const workspace = await initializeWorkspace(data.user.id, data.session.access_token).catch((err) => {
      console.error("[Auth] Google workspace init failed:", err);
      return null;
    });
    await ensureOwnerRole(data.user.id, data.user.email);
    res.status(200).json({
      user: { id: data.user.id, email: data.user.email },
      session: {
        accessToken: data.session.access_token,
        refreshToken: data.session.refresh_token,
        expiresAt: data.session.expires_at
      },
      workspace
    });
  });
}

